const require_project_writer = require("./project-writer-Dv1dPqZX.cjs");
const require_binary_writer = require("./binary-writer-DknjZH0x.cjs");
//#region src/io/platform-io.ts
/**
* Abstract I/O base class for reading and writing FairyGUI projects.
*
* Platform-specific adapters provide the file system abstraction required by
* the reader/writer.
*
* @category I/O
*/
var PlatformIO = class {
	async readProject(projectPath, options) {
		return new require_project_writer.ProjectReader(this.createFileSystem()).read(projectPath, options);
	}
	async readProjectDetailed(projectPath, options) {
		return new require_project_writer.ProjectReader(this.createFileSystem()).readDetailed(projectPath, options);
	}
	async writeProject(doc, projectPath, options) {
		return new require_project_writer.ProjectWriter(this.createFileSystem()).write(doc, projectPath, options);
	}
	async readBinary(filePath, options) {
		return new require_binary_writer.BinaryReader(this.createFileSystem(), options).read(filePath);
	}
	async writeBinary(doc, filePath, options) {
		return new require_binary_writer.BinaryWriter(this.createFileSystem()).write(doc, filePath, options);
	}
};
//#endregion
Object.defineProperty(exports, "PlatformIO", {
	enumerable: true,
	get: function() {
		return PlatformIO;
	}
});
